import{_ as t,o,c as a,ag as n}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"Export to Hoppscotch","description":"","frontmatter":{},"headers":[],"relativePath":"guide/export-hoppscotch.md","filePath":"guide/export-hoppscotch.md","lastUpdated":1785990345000}'),s={name:"guide/export-hoppscotch.md"};function r(c,e,l,i,p,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="export-to-hoppscotch" tabindex="-1">Export to Hoppscotch <a class="header-anchor" href="#export-to-hoppscotch" aria-label="Permalink to &quot;Export to Hoppscotch&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta feature</p><p>Hoppscotch export is disabled by default. Enable <strong>Hoppscotch (Beta)</strong> in the <strong>Features</strong> tab before using it.</p></div><p>EasyYapi can export HTTP endpoints as a Hoppscotch collection. The channel supports both a local JSON file and upload to a Hoppscotch server.</p><h2 id="enable-the-channel" tabindex="-1">Enable the channel <a class="header-anchor" href="#enable-the-channel" aria-label="Permalink to &quot;Enable the channel&quot;">​</a></h2><p>Open <strong>Settings</strong> &gt; <strong>Other Settings</strong> &gt; <strong>EasyApi</strong> &gt; <strong>Features</strong>. Under <strong>Export Channels</strong>, enable <strong>Hoppscotch (Beta)</strong>.</p><p>For cloud upload, open the Hoppscotch settings tab and either log in with the browser flow or enter an access token manually. Without a token, the export remains a local file export.</p><h2 id="export-a-collection" tabindex="-1">Export a collection <a class="header-anchor" href="#export-a-collection" aria-label="Permalink to &quot;Export a collection&quot;">​</a></h2><ol><li>Open a file containing API endpoints, or select files/folders in the Project view.</li><li>Choose <strong>EasyYapi</strong> &gt; <strong>Export</strong> &gt; <strong>Hoppscotch (Beta)</strong>.</li><li>If you are not logged in, choose an output directory and file name. The default file is <code>hoppscotch_collection.json</code>.</li><li>If you are logged in, choose <strong>(New) Create new collection</strong> or select an existing collection to update.</li></ol><p>When no token is configured, the generated JSON can be imported into Hoppscotch manually. With a token, EasyYapi uploads the collection through the Hoppscotch API.</p><h2 id="server-and-self-hosted-settings" tabindex="-1">Server and self-hosted settings <a class="header-anchor" href="#server-and-self-hosted-settings" aria-label="Permalink to &quot;Server and self-hosted settings&quot;">​</a></h2><p>The Hoppscotch settings tab provides:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Server URL</strong></td><td>Hoppscotch server URL; defaults to <code>https://hoppscotch.io</code>.</td></tr><tr><td><strong>Backend URL</strong></td><td>Optional backend API URL for a self-hosted deployment.</td></tr><tr><td><strong>Login / Logout</strong></td><td>Start or clear the browser-based Hoppscotch session.</td></tr><tr><td><strong>Manual Token</strong></td><td>Fallback access token when browser login is unavailable.</td></tr></tbody></table><p>Hoppscotch export is HTTP-only; gRPC endpoints are not included in the collection.</p><h2 id="updating-an-existing-collection" tabindex="-1">Updating an existing collection <a class="header-anchor" href="#updating-an-existing-collection" aria-label="Permalink to &quot;Updating an existing collection&quot;">​</a></h2><p>Updating a collection uses a create-first-then-delete flow. EasyYapi asks for confirmation because the replacement collection receives a new ID. Shared links to the old collection therefore stop working after the update.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>The following channel rules can customize the collection:</p><ul><li><code>hopp.host</code> — override the collection host</li><li><code>hopp.prerequest</code>, <code>hopp.class.prerequest</code>, and <code>hopp.collection.prerequest</code> — add pre-request scripts at endpoint, class, or collection scope</li><li><code>hopp.test</code>, <code>hopp.class.test</code>, and <code>hopp.collection.test</code> — add response tests</li><li><code>hopp.format.after</code> — run after collection formatting</li></ul><p>See <a href="/settings/config-rule">Config Rules</a> for rule syntax.</p>',19)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
